(async () => {
  const rows = await FileAttachment("caravel_ab.csv").csv({typed: true});
  const t = v => rows.filter(r => r.variant === v).reduce((a, r) => ({n: a.n + r.visitors, c: a.c + r.conversions}), {n: 0, c: 0});
  const A = t("control"), B = t("new_checkout");
  const pA = A.c / A.n, pB = B.c / B.n, p = (A.c + B.c) / (A.n + B.n);
  const se = Math.sqrt(p * (1 - p) * (1 / A.n + 1 / B.n));
  const z = (pB - pA) / se;
  const phi = x => { const s = x < 0 ? -1 : 1; x = Math.abs(x) / Math.SQRT2; const k = 1 / (1 + 0.3275911 * x);
    const y = 1 - (((((1.061405429 * k - 1.453152027) * k) + 1.421413741) * k - 0.284496736) * k + 0.254829592) * k * Math.exp(-x * x); return 0.5 * (1 + s * y); };
  const pv = 2 * (1 - phi(Math.abs(z)));
  const sed = Math.sqrt(pA * (1 - pA) / A.n + pB * (1 - pB) / B.n);
  const f = x => (100 * x).toFixed(2) + "%";
  return Inputs.table([
    {step: "control conv / visitors", value: `${A.c} / ${A.n} = ${f(pA)}`},
    {step: "new conv / visitors", value: `${B.c} / ${B.n} = ${f(pB)}`},
    {step: "absolute diff", value: f(pB - pA)},
    {step: "relative lift (summary says 12%)", value: f(pB / pA - 1)},
    {step: "pooled rate", value: f(p)},
    {step: "SE = √(p(1−p)(1/nA+1/nB))", value: se.toFixed(5)},
    {step: "z = diff / SE", value: z.toFixed(3)},
    {step: "two-sided p (summary says 0.004)", value: pv.toFixed(3)},
    {step: "95% CI of diff (pp)", value: `${(100*(pB-pA-1.96*sed)).toFixed(2)} to ${(100*(pB-pA+1.96*sed)).toFixed(2)}`}
  ], {columns: ["step", "value"], layout: "auto"});
})()

